// @ai:generated by=claude-opus-4-7 date=2026-06-21
// @ai:purpose 為 Go 原始檔自動產生缺少的 *_test.go 骨架
// Package testgen 掃描 Go 原始檔的 exported func / method，找出尚未存在的 Test*，
// 並生成對應的測試骨架檔案（或追加到既有 *_test.go）。
//
// 設計原則：
//   - 不覆蓋既有 Test*（即使是空殼也保留）
//   - 不假裝有測試 → 骨架預設 t.Skip("auto-generated stub")，CI 看得到
//   - 純 AST 分析，不執行程式碼
//   - 跳過明確標記 //hyp:notest 的函式與自動產生的檔案（// Code generated ... DO NOT EDIT.）
//   - 以整個套件判斷是否已有測試：同目錄所有 *_test.go（含 package x_test）
//     中 Test<名稱> 開頭、且其後不是小寫字母的測試都算（TestAddWorks、TestAdd_Overflow）
//   - 依簽名產生 table-driven 骨架（參數 / want / wantErr）；HypGo handler 與路由註冊函式
//     不補單元測試，改在根註冊函式旁產生 contract.TestAll 測試（見 render.go）
package testgen

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/build/constraint"
	"go/format"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Report 描述單一檔案的處理結果
type Report struct {
	SourceFile string   // 原始 .go 檔案
	TestFile   string   // 對應的 *_test.go
	Created    bool     // 是否第一次建立 test 檔
	Added      []string // 新加入的 Test 函式名稱
	Skipped    []string // 已存在的 Test 名稱（被跳過）
	NoTestNeed []string // 標記 //hyp:notest 而被略過的函式
	// Contract 交給 contract 測試涵蓋、不補單元測試的 handler 與路由註冊函式
	Contract []string
	// ContractFile 本次寫入 contract 測試的檔案（<src>_contract_test.go）；未寫入時為空
	ContractFile string
	// BuildMismatch 沒有產生的測試：既有測試檔的 build 條件與原始檔不同，追加進去在某些平台會編不過
	BuildMismatch []string
}

// SkippedError 由 GenerateForDir 回傳：有目錄或檔案無法處理（其餘的照常完成，reports 仍然有效）
type SkippedError struct {
	Problems []string // "<路徑>: <原因>"
}

func (e *SkippedError) Error() string {
	return fmt.Sprintf("%d location(s) could not be processed:\n  %s", len(e.Problems), strings.Join(e.Problems, "\n  "))
}

// Options 控制產生行為
type Options struct {
	// IncludeUnexported 是否也為 unexported func / method 產生測試
	// 預設 false：只為 exported（首字母大寫）函式產生測試。
	IncludeUnexported bool

	// DryRun 為 true 時只回報會做什麼，不寫入任何檔案
	DryRun bool

	// Comment 寫在 t.Skip 訊息裡的提示文字，預設 "auto-generated stub; replace with real assertions"
	StubMessage string
}

// DefaultOptions 回傳預設 Options
func DefaultOptions() Options {
	return Options{
		IncludeUnexported: false,
		DryRun:            false,
		StubMessage:       "auto-generated stub; replace with real assertions",
	}
}

// GenerateForFile 為單一 .go 檔生成缺少的測試骨架
// 已存在的 Test* 不會被覆蓋；是否已有測試以整個套件（同目錄）判斷。
func GenerateForFile(filename string, opts Options) (*Report, error) {
	if !strings.HasSuffix(filename, ".go") {
		return nil, fmt.Errorf("not a .go file: %s", filename)
	}
	if strings.HasSuffix(filename, "_test.go") {
		return nil, fmt.Errorf("cannot process *_test.go directly: %s", filename)
	}
	pkg, err := loadPkgContext(filepath.Dir(filename), opts)
	if err != nil {
		return nil, err
	}
	return generateFile(filename, pkg, opts)
}

// generateFile 依套件現況為單一原始檔補上缺少的測試骨架；新增的名稱記回 pkg，
// 同套件後續的檔案不會再產生同名測試
func generateFile(filename string, pkg *pkgContext, opts Options) (*Report, error) {
	srcContent, err := os.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("read source: %w", err)
	}

	fset := token.NewFileSet()
	srcAST, err := parser.ParseFile(fset, filename, srcContent, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parse source: %w", err)
	}

	// 推導 test 檔案路徑：foo.go → foo_test.go（同目錄）
	testPath := strings.TrimSuffix(filename, ".go") + "_test.go"
	report := &Report{SourceFile: filename, TestFile: testPath}

	// 自動產生的檔案（protoc、stringer…）不補測試：先前 .pb.go 的 getter 也會各得一個空殼
	if ast.IsGenerated(srcAST) {
		return report, nil
	}

	// //go:build ignore 的檔案不參與建置（多半是另一個 package main 的產生器）：不補測試。
	// 先前照樣產生 gen_test.go，套件變成「found packages x and main」，連 setup 都失敗
	buildLine, ignored := buildConstraint(srcAST)
	if ignored {
		return report, nil
	}

	// 收集本檔案中需要被測試的函式
	candidates := collectCandidates(srcAST, opts, pkg.funcTypes)

	// 把標記 notest 的函式也記錄
	for _, c := range candidates {
		if c.skipNoTest {
			report.NoTestNeed = append(report.NoTestNeed, c.testName)
		}
	}
	candidates = filterNoTest(candidates)
	if len(candidates) == 0 {
		return report, nil
	}

	pkgName := srcAST.Name.Name
	unitFile := readTestFile(testPath)
	contractPath := strings.TrimSuffix(filename, ".go") + "_contract_test.go"
	contractFile := readTestFile(contractPath)
	// 既有測試檔的 build 條件要與原始檔相同才追加。先前不看條件：//go:build linux 的原始檔
	// 對應沒有條件的測試檔，在其他平台 undefined
	fits := func(tf testFile) bool { return !tf.exists || tf.build == buildLine }

	var units, contracts []candidate
	for _, c := range candidates {
		switch {
		case c.kind == kindHandler || (c.kind == kindRegistrar && (c.isMethod || pkg.calledRegistrars[c.funcName])):
			// handler 與非根註冊函式由根註冊函式的 contract 測試涵蓋
			report.Contract = append(report.Contract, c.funcName)
			continue
		case c.kind == kindRegistrar:
			// contract 測試呼叫未限定名稱的註冊函式：檔案若是 package x_test 就無法寫入
			if !contractFile.accepts(pkgName, nil) {
				report.Contract = append(report.Contract, c.funcName)
				continue
			}
		case c.kind == kindTable && !unitFile.accepts(pkgName, c.spec.imports):
			c.kind = kindStub // 既有測試檔是 package x_test 或 import 名稱衝突：骨架無法直接呼叫
		}
		by := pkg.covered(c.testName)
		// 未匯出的名稱：手寫的測試多半叫 TestAdd 而不是 Test_add，兩種都算
		if by == "" && c.altName != "" && !pkg.isCandidate(c.altName) {
			by = pkg.covered(c.altName)
		}
		if by != "" && pkg.generated[by] != "" && pkg.generated[by] != c.funcName && by == c.testName {
			// 這次執行才為另一個函式產生的同名測試（方法 Foo.Bar 與函式 Foo_Bar 都對應 TestFoo_Bar）：
			// 先前把後者列為 kept，其實沒有任何測試在測它
			by = ""
			for pkg.tests[c.testName] {
				c.testName += "_2"
			}
		}
		if by != "" {
			// 不是同名的測試時寫出是哪一個，名稱相近而誤認時看得出來
			if by != c.testName {
				report.Skipped = append(report.Skipped, fmt.Sprintf("%s (by %s)", c.testName, by))
			} else {
				report.Skipped = append(report.Skipped, c.testName)
			}
			continue
		}
		target := unitFile
		if c.kind == kindRegistrar {
			target = contractFile
		}
		if !fits(target) {
			report.BuildMismatch = append(report.BuildMismatch, c.testName)
			continue
		}
		if c.kind == kindRegistrar {
			c.testName += "_Contracts"
			contracts = append(contracts, c)
		} else {
			units = append(units, c)
		}
		report.Added = append(report.Added, c.testName)
		pkg.tests[c.testName] = true
		pkg.generated[c.testName] = c.funcName
	}

	if len(units) == 0 && !unitFile.exists {
		report.TestFile = "" // 不會建立單元測試檔：報表不顯示 → TestFile
	}
	if len(units)+len(contracts) == 0 {
		return report, nil
	}
	report.Created = len(units) > 0 && !unitFile.exists // 有東西要寫才算建立（先前全部已覆蓋時也回報 created）
	if len(contracts) > 0 {
		report.ContractFile = contractPath
	}
	if opts.DryRun {
		return report, nil
	}

	if len(units) > 0 {
		if err := writeTests(testPath, pkgName, buildLine, unitFile, units, opts); err != nil {
			return nil, fmt.Errorf("write %s: %w", testPath, err)
		}
	}
	if len(contracts) > 0 {
		if err := writeTests(contractPath, pkgName, buildLine, contractFile, contracts, opts); err != nil {
			return nil, fmt.Errorf("write %s: %w", contractPath, err)
		}
	}
	return report, nil
}

// GenerateForDir 遞迴處理 rootDir 下的所有 .go 檔。跳過 vendor / node_modules / testdata 與
// `.`、`_` 開頭的目錄（Go 不建置它們；先前 .cache、_examples、.claude/worktrees 裡也會被寫入測試檔）。
// 有目錄或檔案無法處理時其餘的照常完成，回傳 reports 與 *SkippedError
func GenerateForDir(rootDir string, opts Options) ([]Report, error) {
	var reports []Report
	var problems []string
	pkgs := map[string]*pkgContext{} // 每個目錄的套件現況只讀一次
	err := filepath.WalkDir(rootDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			name := d.Name()
			if path != rootDir && (name == "vendor" || name == "node_modules" || name == "testdata" ||
				strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_")) {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		dir := filepath.Dir(path)
		pkg, ok := pkgs[dir]
		if !ok {
			var loadErr error
			if pkg, loadErr = loadPkgContext(dir, opts); loadErr != nil {
				problems = append(problems, fmt.Sprintf("%s: %v", dir, loadErr))
				pkg = nil
			}
			pkgs[dir] = pkg
		}
		if pkg == nil {
			return nil // 該目錄的測試檔無法解析：不猜，整個目錄跳過
		}
		rep, genErr := generateFile(path, pkg, opts)
		if genErr != nil {
			problems = append(problems, fmt.Sprintf("%s: %v", path, genErr))
			return nil
		}
		if rep != nil && !rep.empty() {
			reports = append(reports, *rep)
		}
		return nil
	})
	// 先前只在 stderr 印一行就繼續，結尾照樣是「No missing tests found.」、exit 0
	if err == nil && len(problems) > 0 {
		err = &SkippedError{Problems: problems}
	}
	return reports, err
}

// empty 回報這個檔案是否沒有任何值得列出的結果
func (r *Report) empty() bool {
	return len(r.Added) == 0 && len(r.Skipped) == 0 && len(r.NoTestNeed) == 0 && len(r.Contract) == 0 && len(r.BuildMismatch) == 0
}

// IsEmpty 回報這個檔案是否沒有任何值得列出的結果
func (r *Report) IsEmpty() bool { return r == nil || r.empty() }

// buildConstraint 回傳原始檔的 build 條件（正規化成 //go:build 的寫法；沒有時為空字串），
// 以及它是否一定需要 ignore tag
func buildConstraint(f *ast.File) (line string, ignored bool) {
	for _, group := range f.Comments {
		if group.Pos() >= f.Package {
			break
		}
		for _, c := range group.List {
			if !constraint.IsGoBuild(c.Text) && !constraint.IsPlusBuild(c.Text) {
				continue
			}
			expr, err := constraint.Parse(c.Text)
			if err != nil {
				continue
			}
			if requiresIgnore(expr) {
				return "", true
			}
			if line == "" {
				line = "//go:build " + expr.String()
			} else { // 多行 // +build 之間是 AND
				line = "//go:build (" + strings.TrimPrefix(line, "//go:build ") + ") && (" + expr.String() + ")"
			}
			if constraint.IsGoBuild(c.Text) {
				return "//go:build " + expr.String(), false // 有 //go:build 時以它為準
			}
		}
	}
	return line, false
}

// requiresIgnore 回報條件是否一定需要 ignore tag（ignore、ignore && x）
func requiresIgnore(expr constraint.Expr) bool {
	switch e := expr.(type) {
	case *constraint.TagExpr:
		return e.Tag == "ignore"
	case *constraint.AndExpr:
		return requiresIgnore(e.X) || requiresIgnore(e.Y)
	}
	return false
}

// pkgContext 一個目錄（Go 套件）的測試現況。先前只看成對的 foo_test.go 裡有沒有
// 完全同名的 Test：測試寫在其他測試檔就重複產生（TestAdd redeclared，整個套件編不過），
// 換個名字的測試（TestAddWorks）也認不得
type pkgContext struct {
	tests      map[string]bool // 目錄下所有 *_test.go 的 Test*（含 package x_test）與本次新增的
	candidates []string        // 目錄下所有原始檔候選的 Test 名稱，用來把 TestAddUser 歸給 AddUser 而非 Add
	// calledRegistrars 被同套件其他路由註冊函式呼叫的註冊函式（如 Setup 內的 RegisterUserRoutes）：
	// 它們的路由已由根註冊函式的 contract 測試涵蓋
	calledRegistrars map[string]bool
	funcTypes        map[string]bool   // 套件內宣告的函式型別（type Handler func(...)）
	generated        map[string]string // 這次執行產生的測試 → 它測的函式
}

// loadPkgContext 讀取目錄下所有 .go 檔：測試檔收集 Test*，原始檔收集候選名稱。
// 測試檔語法錯誤時回傳錯誤（無法得知已有哪些測試，寧可不產生）
func loadPkgContext(dir string, opts Options) (*pkgContext, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	pkg := &pkgContext{tests: map[string]bool{}, calledRegistrars: map[string]bool{},
		funcTypes: map[string]bool{}, generated: map[string]string{}}
	registrars := map[string]*ast.FuncDecl{}
	fset := token.NewFileSet()
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") {
			continue
		}
		path := filepath.Join(dir, name)
		if strings.HasSuffix(name, "_test.go") {
			f, err := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
			if err != nil {
				return nil, fmt.Errorf("parse existing test file %s: %w", path, err)
			}
			for _, decl := range f.Decls {
				if fd, ok := decl.(*ast.FuncDecl); ok && fd.Recv == nil && strings.HasPrefix(fd.Name.Name, "Test") {
					pkg.tests[fd.Name.Name] = true
				}
			}
			continue
		}
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments|parser.SkipObjectResolution)
		if err != nil || ast.IsGenerated(f) {
			continue // 原始檔錯誤由 generateFile 回報
		}
		if _, ignored := buildConstraint(f); ignored {
			continue
		}
		for _, decl := range f.Decls {
			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.TYPE {
				for _, s := range gd.Specs {
					if ts, ok := s.(*ast.TypeSpec); ok {
						if _, isFunc := ts.Type.(*ast.FuncType); isFunc {
							pkg.funcTypes[ts.Name.Name] = true
						}
					}
				}
			}
		}
		for _, c := range collectCandidates(f, opts, nil) {
			pkg.candidates = append(pkg.candidates, c.testName)
			if c.kind == kindRegistrar && !c.isMethod {
				registrars[c.funcName] = c.fd
			}
		}
	}
	for name, fd := range registrars {
		ast.Inspect(fd.Body, func(n ast.Node) bool {
			if call, ok := n.(*ast.CallExpr); ok {
				if id, ok := call.Fun.(*ast.Ident); ok && id.Name != name && registrars[id.Name] != nil {
					pkg.calledRegistrars[id.Name] = true
				}
			}
			return true
		})
	}
	return pkg, nil
}

// covers 回報測試 test 是否以 target 命名：完全相同，或其後接的不是小寫字母
// （TestAddWorks、TestAdd_Overflow、TestAdd2 都算 TestAdd；TestAddress 不算）
func covers(test, target string) bool {
	if !strings.HasPrefix(test, target) {
		return false
	}
	if len(test) == len(target) {
		return true
	}
	r, _ := utf8.DecodeRuneInString(test[len(target):])
	return !unicode.IsLower(r)
}

// isCandidate 回報 name 是否為套件內某個函式的測試名稱
func (p *pkgContext) isCandidate(name string) bool {
	for _, c := range p.candidates {
		if c == name {
			return true
		}
	}
	return false
}

// covered 回傳套件內在測 target 的測試名稱（沒有時為空字串；同名的優先）。一個測試同時符合多個候選時
// 歸給名稱最長者：有 AddUser 時 TestAddUserWorks 算 AddUser 的測試，不算 Add 的
func (p *pkgContext) covered(target string) string {
	if p.tests[target] {
		return target
	}
	names := make([]string, 0, len(p.tests))
	for test := range p.tests {
		names = append(names, test)
	}
	sort.Strings(names)
	for _, test := range names {
		if !covers(test, target) {
			continue
		}
		owner := target
		for _, c := range p.candidates {
			if len(c) > len(owner) && covers(test, c) {
				owner = c
			}
		}
		if owner == target {
			return test
		}
	}
	return ""
}

// --- internal ---

type candidate struct {
	funcName    string // 原始函式名（含 receiver 樣式：Svc_DoThing）
	testName    string // 對應的 Test 名稱
	altName     string // 未匯出的名稱另一種常見的測試寫法（add → TestAdd）；沒有時為空
	isMethod    bool
	receiverStr string // 用於 method（例：*Svc）
	skipNoTest  bool   // 是否標記 //hyp:notest
	kind        candKind
	spec        *tableSpec // kind == kindTable 時的骨架內容
	fd          *ast.FuncDecl
}

// collectCandidates 從 AST 抽出所有要產測試的 func / method
func collectCandidates(f *ast.File, opts Options, funcTypes map[string]bool) []candidate {
	var out []candidate
	imps := fileImports(f)

	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		name := fd.Name.Name
		// 跳過已經是 Test/Benchmark/Example/Fuzz 前綴的（雖然這檔不該是 _test.go，仍保險過濾）
		if isReservedTestPrefix(name) {
			continue
		}
		if !opts.IncludeUnexported && !ast.IsExported(name) {
			continue
		}

		c := candidate{funcName: name, fd: fd, kind: classify(fd, imps)}
		if c.kind == kindTable {
			c.spec = newTableSpec(fd, imps)
			c.spec.markFuncResults(fd, funcTypes)
		}
		if fd.Recv != nil && len(fd.Recv.List) > 0 {
			c.isMethod = true
			recv := fd.Recv.List[0].Type
			c.receiverStr = exprString(recv)
			c.testName, c.altName = testNames(recvBaseName(recv), "_"+name)
		} else {
			c.testName, c.altName = testNames(name, "")
		}

		// 檢查 doc comment 是否含 //hyp:notest
		if fd.Doc != nil {
			for _, cm := range fd.Doc.List {
				if strings.Contains(cm.Text, "//hyp:notest") || strings.Contains(cm.Text, "// hyp:notest") {
					c.skipNoTest = true
					break
				}
			}
		}

		out = append(out, c)
	}
	return out
}

// testNames 組出測試名稱。Test 之後的第一個字母不能是小寫（go vet 會擋下，go test 也不會執行）：
// 未匯出的名稱前面加底線，與 gotests 的慣例相同（add → Test_add、server.ServeHTTP → Test_server_ServeHTTP）。
// 先前直接接上，未匯出型別上的匯出方法產生 Testserver_ServeHTTP，整個套件的測試編不過。
// alt 是首字母改大寫的寫法，手寫的測試多半用它
func testNames(first, rest string) (name, alt string) {
	if ast.IsExported(first) {
		return "Test" + first + rest, ""
	}
	r, size := utf8.DecodeRuneInString(first)
	return "Test_" + first + rest, "Test" + string(unicode.ToUpper(r)) + first[size:] + rest
}

func filterNoTest(in []candidate) []candidate {
	var out []candidate
	for _, c := range in {
		if !c.skipNoTest {
			out = append(out, c)
		}
	}
	return out
}

func isReservedTestPrefix(name string) bool {
	for _, prefix := range []string{"Test", "Benchmark", "Example", "Fuzz"} {
		if strings.HasPrefix(name, prefix) && len(name) > len(prefix) {
			next := name[len(prefix)]
			if next >= 'A' && next <= 'Z' || next == '_' {
				return true
			}
		}
	}
	return false
}

// exprString 把 receiver 型別還原成原始碼寫法（僅用於註解），如 *List[T]
func exprString(e ast.Expr) string {
	switch v := e.(type) {
	case *ast.Ident:
		return v.Name
	case *ast.StarExpr:
		return "*" + exprString(v.X)
	case *ast.SelectorExpr:
		return exprString(v.X) + "." + v.Sel.Name
	case *ast.ParenExpr:
		return "(" + exprString(v.X) + ")"
	case *ast.IndexExpr:
		return exprString(v.X) + "[" + exprString(v.Index) + "]"
	case *ast.IndexListExpr:
		params := make([]string, len(v.Indices))
		for i, ix := range v.Indices {
			params[i] = exprString(ix)
		}
		return exprString(v.X) + "[" + strings.Join(params, ", ") + "]"
	default:
		return fmt.Sprintf("%T", e)
	}
}

// recvBaseName 取 receiver 的型別名稱（去掉 *、括號與型別參數），用於組 Test 名稱。
// 先前泛型 receiver（*List[T]）落到 %T，產生 Test*ast.IndexExpr_Push 這種無法編譯的名稱
func recvBaseName(e ast.Expr) string {
	for {
		switch v := e.(type) {
		case *ast.StarExpr:
			e = v.X
		case *ast.ParenExpr:
			e = v.X
		case *ast.IndexExpr:
			e = v.X
		case *ast.IndexListExpr:
			e = v.X
		case *ast.Ident:
			return v.Name
		default:
			return "Recv"
		}
	}
}

// testFile 既有測試檔的狀態（不存在時 exists 為 false）
type testFile struct {
	exists  bool
	pkgName string
	imports map[string]string // import path → 引用名稱
	build   string            // build 條件（見 buildConstraint）
}

func readTestFile(path string) testFile {
	f, err := parser.ParseFile(token.NewFileSet(), path, nil, parser.ImportsOnly|parser.ParseComments)
	if err != nil {
		_, statErr := os.Stat(path)
		return testFile{exists: statErr == nil}
	}
	tf := testFile{exists: true, pkgName: f.Name.Name, imports: map[string]string{}}
	tf.build, _ = buildConstraint(f)
	for _, imp := range f.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		name := guessPkgName(path)
		if imp.Name != nil {
			name = imp.Name.Name
		}
		tf.imports[path] = name
	}
	return tf
}

// accepts 回報骨架能否寫進這個測試檔：不存在、或同為 pkgName 套件（骨架以未限定名稱呼叫目標），
// 且 specs 需要的 import 沒有以其他名稱引入
func (tf testFile) accepts(pkgName string, specs []string) bool {
	if !tf.exists {
		return true
	}
	if tf.pkgName != pkgName {
		return false
	}
	for _, s := range specs {
		path, _ := strconv.Unquote(s[strings.LastIndex(s, " ")+1:])
		name := guessPkgName(path)
		if i := strings.LastIndex(s, " "); i > 0 {
			name = s[:i]
		}
		if have, ok := tf.imports[path]; ok && have != name {
			return false
		}
		// 同一個名稱已經給了別的套件（原始檔的 errors 是 x/errors，測試檔引入的是標準庫 errors）：
		// 先前照樣補上，結果 errors redeclared
		for p, have := range tf.imports {
			if have == name && p != path {
				return false
			}
		}
	}
	return true
}

// requiredImports 回傳這批骨架需要的 import spec
func requiredImports(items []candidate) []string {
	set := map[string]bool{`"testing"`: true}
	for _, c := range items {
		switch c.kind {
		case kindTable:
			for _, s := range c.spec.imports {
				set[s] = true
			}
			if c.spec.needsReflect() {
				set[`"reflect"`] = true
			}
		case kindRegistrar:
			set[strconv.Quote(hypRouterPath)] = true
			set[strconv.Quote(hypContractPath)] = true
		}
	}
	out := make([]string, 0, len(set))
	for s := range set {
		out = append(out, s)
	}
	sort.Strings(out)
	return out
}

// writeTests 把骨架寫進 path：既有檔案補上缺少的 import 後追加（不重排使用者的檔案），否則建立新檔
func writeTests(path, pkgName, buildLine string, tf testFile, items []candidate, opts Options) error {
	var body strings.Builder
	for _, c := range items {
		body.WriteString("\n" + renderTestStub(c, opts))
	}
	imports := requiredImports(items)

	if tf.exists {
		src, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		// 原本就是 gofmt 排好的檔案，補完之後再排一次（補進去的 import 才會在排序後的位置）；
		// 不是的話只做文字插入，不動使用者的排版
		formatted, ferr := format.Source(src)
		clean := ferr == nil && bytes.Equal(formatted, src)
		crlf := bytes.Contains(src, []byte("\r\n"))
		src, err = addImports(src, imports)
		if err != nil {
			return err
		}
		out := append(src, body.String()...)
		if clean {
			if formatted, ferr := format.Source(out); ferr == nil {
				out = formatted
			}
		} else if crlf {
			// 檔案是 CRLF：補進去的內容也用 CRLF，不留下混合的行尾
			out = bytes.ReplaceAll(bytes.ReplaceAll(out, []byte("\r\n"), []byte("\n")), []byte("\n"), []byte("\r\n"))
		}
		return os.WriteFile(path, out, 0644)
	}

	var sb strings.Builder
	if buildLine != "" {
		sb.WriteString(buildLine + "\n\n")
	}
	// 不寫 "Code generated"：這個檔案是要讓人改的，有些工具看到那幾個字就把整個檔案當成生成檔略過
	sb.WriteString("// Test stubs created by hyp testgen: replace each t.Skip with real assertions.\n\n")
	fmt.Fprintf(&sb, "package %s\n\nimport (\n", pkgName)
	// 標準庫一組、其餘一組（gofmt 只排序不分組）
	for _, std := range []bool{true, false} {
		group := false
		for _, s := range imports {
			if isStdImport(s[strings.LastIndex(s, " ")+1:]) == std {
				sb.WriteString("\t" + s + "\n")
				group = true
			}
		}
		if std && group {
			sb.WriteString("\n")
		}
	}
	sb.WriteString(")\n")
	sb.WriteString(body.String())
	out, err := format.Source([]byte(sb.String()))
	if err != nil {
		out = []byte(sb.String()) // 排版失敗仍寫入，交給 go vet 回報
	}
	return os.WriteFile(path, out, 0644)
}

// isStdImport 回報引號包住的 import 路徑是否為標準庫（第一段不含 "."）
func isStdImport(quoted string) bool {
	path, _ := strconv.Unquote(quoted)
	first, _, _ := strings.Cut(path, "/")
	return !strings.Contains(first, ".")
}

// renderTestStub 產生單一 Test 函式：空殼、table-driven 骨架或 contract 測試
func renderTestStub(c candidate, opts Options) string {
	msg := opts.StubMessage
	if msg == "" {
		msg = "auto-generated stub"
	}
	if c.kind == kindRegistrar {
		return formatDecl(renderContract(c))
	}
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("// %s — auto-generated stub for %s\n", c.testName, c.funcName))
	if c.isMethod {
		sb.WriteString(fmt.Sprintf("// Target: (%s).%s\n", c.receiverStr, c.funcName))
	} else {
		sb.WriteString(fmt.Sprintf("// Target: %s\n", c.funcName))
	}
	if c.kind == kindTable {
		sb.WriteString(c.spec.render(c, msg))
		return formatDecl(sb.String())
	}
	sb.WriteString(fmt.Sprintf("func %s(t *testing.T) {\n", c.testName))
	sb.WriteString(fmt.Sprintf("\tt.Skip(%q)\n", msg))
	sb.WriteString("}\n")
	return sb.String()
}

// FormatReports 把 GenerateForDir 的結果整理成終端可讀的報告
func FormatReports(reports []Report) string {
	var sb strings.Builder
	created, added, skipped, notest, contract := 0, 0, 0, 0, 0
	for _, r := range reports {
		if r.empty() {
			continue
		}
		mark := "~"
		if r.Created {
			mark = "+"
			created++
		}
		if r.TestFile == "" {
			sb.WriteString(fmt.Sprintf("  · %s\n", r.SourceFile))
		} else {
			sb.WriteString(fmt.Sprintf("  %s %s → %s\n", mark, r.SourceFile, r.TestFile))
		}
		if len(r.Added) > 0 {
			added += len(r.Added)
			sb.WriteString(fmt.Sprintf("      added:    %s\n", strings.Join(r.Added, ", ")))
		}
		if len(r.Skipped) > 0 {
			skipped += len(r.Skipped)
			sb.WriteString(fmt.Sprintf("      kept:     %s\n", strings.Join(r.Skipped, ", ")))
		}
		if len(r.NoTestNeed) > 0 {
			notest += len(r.NoTestNeed)
			sb.WriteString(fmt.Sprintf("      notest:   %s\n", strings.Join(r.NoTestNeed, ", ")))
		}
		if len(r.Contract) > 0 {
			contract += len(r.Contract)
			sb.WriteString(fmt.Sprintf("      contract: %s\n", strings.Join(r.Contract, ", ")))
		}
		if r.ContractFile != "" {
			sb.WriteString(fmt.Sprintf("      contract test → %s\n", r.ContractFile))
		}
		if len(r.BuildMismatch) > 0 {
			sb.WriteString(fmt.Sprintf("      not added (the existing test file has a different build constraint): %s\n", strings.Join(r.BuildMismatch, ", ")))
		}
	}
	sb.WriteString(fmt.Sprintf("\nSummary: %d files (created=%d), %d Test stubs added, %d kept, %d marked //hyp:notest, %d covered by contract tests\n",
		len(reports), created, added, skipped, notest, contract))
	return sb.String()
}
